# Extracted from the local PhaseSNN implementation; see NOTICE and LICENSE.
# Hadamard helpers adapted from QuaRot / QuIP#; see NOTICE.
import torch
import fast_hadamard_transform


def get_hadK(n):
    # The migrated 1.5B checkpoint has intermediate_size=8960=140*64.
    if n % 140 == 0 and is_pow2(n // 140):
        return get_had140(), 140
    if is_pow2(n):
        return None, 1
    raise ValueError(f"Unsupported Hadamard dimension {n}; this runtime supports powers of two and 140 times powers of two")

def matmul_hadU_cuda(X, hadK, K):
    n = X.shape[-1]
    if K == 1:
        return fast_hadamard_transform.hadamard_transform(X.contiguous(), 1.0/torch.tensor(n).sqrt())
    # if transpose:
    #     hadK = hadK.T.contiguous()
    input = X.view(-1, K, n // K)
    input = fast_hadamard_transform.hadamard_transform(input.contiguous(), 1.0/torch.tensor(n).sqrt())
    input = hadK.to(input.device).to(input.dtype) @ input
    return input.reshape(X.shape)

def is_pow2(n):
    return (n & (n - 1) == 0) and (n > 0)

